// 02a. Identify execution type
// Routes document events, daily risk reports, and reviewer decisions without relying on trigger order.
return $input.all().map((item) => {
  const binaryKeys = Object.keys(item.binary || {});
  const explicitType = String(item.json?.executionType || '').trim();
  const hasDocument = binaryKeys.length > 0;
  const hasEmailEnvelope = Boolean(item.json?.id || item.json?.messageId || item.json?.threadId);
  const executionType = explicitType || (hasDocument ? 'document' : (hasEmailEnvelope ? 'ignore' : 'ignore'));
  return {
    json: { ...item.json, executionType },
    binary: item.binary || {},
  };
});

// 03. Prepare attachments
// Creates one item per PDF or image and propagates traceability keys.
const results = [];
const acceptedMimeTypes = /^(application\/pdf|image\/(jpeg|jpg|png|webp))$/i;

for (const item of $input.all()) {
  const sourceMessageId = String(item.json.id || item.json.messageId || item.json.threadId || 'unknown-message');
  const sourceFileEntries = Object.entries(item.binary || {});

  for (const [binaryKey, binary] of sourceFileEntries) {
    const mimeType = String(binary.mimeType || '');
    if (!acceptedMimeTypes.test(mimeType)) continue;

    const sourceFileName = String(binary.fileName || binaryKey || 'pod-document');
    const documentKey = `${sourceMessageId}::${sourceFileName}`;
    results.push({
      json: {
        ...item.json,
        sourceMessageId,
        sourceFileName,
        sourceMimeType: mimeType,
        sourceBinaryKey: binaryKey,
        documentKey,
        correlationKey: documentKey,
        receivedAt: new Date().toISOString(),
      },
      binary: { data: binary },
    });
  }
}

return results;

// 04. Build AI request
// Encodes the file as a data URL and builds a multimodal request without exposing a secret.
const results = [];
const extractionInstructions = `You extract completion evidence documents. Return ONLY valid JSON with this exact schema:
{
  "correlation_key": "string copied exactly from the request",
  "document_type": "proof_of_delivery|delivery_note|completed_work_order|service_report|equipment_return|unknown",
  "document_readable": true,
  "confidence": 0.0,
  "dispatch_reference": null,
  "customer": null,
  "delivery_date": null,
  "recipient_name": null,
  "signature_present": false,
  "notes": null
}
Rules: never invent values; confidence is a number from 0 to 1; delivery_date must be YYYY-MM-DD or null; dispatch_reference is the shipment, order, job, work-order, delivery, or POD reference printed on the document; document_readable is false if the document cannot be reliably read.`;

const inputItems = $input.all();
for (let index = 0; index < inputItems.length; index++) {
  const item = inputItems[index];
  let buffer;
  try {
    buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  } catch (error) {
    results.push({ json: { ...item.json, extractionError: `BINARY_READ_FAILED: ${String(error.message || error)}` }, binary: item.binary || {} });
    continue;
  }

  const dataUrl = `data:${item.json.sourceMimeType};base64,${buffer.toString('base64')}`;
  const attachmentPart = item.json.sourceMimeType === 'application/pdf'
    ? { type: 'file', file: { filename: item.json.sourceFileName, file_data: dataUrl } }
    : { type: 'image_url', image_url: { url: dataUrl } };

  results.push({
    json: {
      ...item.json,
      aiRequestBody: {
        model: item.json.aiModel,
        temperature: 0,
        response_format: { type: 'json_object' },
        messages: [{
          role: 'user',
          content: [
            { type: 'text', text: `${extractionInstructions}\n\nCorrelation key: ${item.json.correlationKey}` },
            attachmentPart,
          ],
        }],
      },
    },
    binary: item.binary || {},
  });
}

return results;

// 06. Normalize extraction
// Restores the context overwritten by HTTP Request by matching the unique key returned by the AI model.
const responses = $input.all();
let upstreamItems = [];
try { upstreamItems = $('Build AI Request').all(); } catch (error) {}

function parseJson(value) {
  if (typeof value === 'object' && value !== null) return value;
  const text = String(value || '').replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  return JSON.parse(text);
}

const results = [];
for (const response of responses) {
  const responseJson = response.json || {};
  let extraction = null;
  let parseError = '';
  try {
    extraction = parseJson(responseJson.choices?.[0]?.message?.content || responseJson.output || responseJson);
  } catch (error) {
    parseError = String(error.message || error);
  }

  const correlationKey = String(extraction?.correlation_key || '');
  const source = upstreamItems.find((entry) => String(entry.json?.correlationKey || '') === correlationKey);
  if (!source) {
    results.push({
      json: {
        extractionError: parseError || 'CONTEXT_NOT_FOUND_AFTER_HTTP_REQUEST',
        needsReview: true,
        status: 'Needs review',
        exceptionReason: 'The AI response could not be correlated with an incoming document.',
      },
    });
    continue;
  }

  const confidence = Number(extraction?.confidence);
  results.push({
    json: {
      ...source.json,
      extraction: {
        documentType: extraction?.document_type || 'unknown',
        documentReadable: extraction?.document_readable === true,
        confidence: Number.isFinite(confidence) ? confidence : 0,
        dispatchReference: String(extraction?.dispatch_reference || '').trim(),
        customer: String(extraction?.customer || '').trim(),
        deliveryDate: String(extraction?.delivery_date || '').trim(),
        recipientName: String(extraction?.recipient_name || '').trim(),
        signaturePresent: extraction?.signature_present === true,
        notes: String(extraction?.notes || '').trim(),
      },
      extractionError: parseError || '',
    },
    binary: source.binary || {},
  });
}

return results;

// 09. Reconcile and decide
// Correlates every POD with a dispatch through its unique reference and prevents a dispatch from entering billing twice.
const existingBillingRows = $input.all().map((item) => item.json || {});
let existingRegisterRows = [];
let dispatchRows = [];
let documentItems = [];
try { existingRegisterRows = $('Read POD Register in Sheets').all().map((item) => item.json || {}); } catch (error) {}
try { dispatchRows = $('Read Dispatches from Sheets').all().map((item) => item.json || {}); } catch (error) {}
try { documentItems = $('Normalize POD Extraction').all(); } catch (error) {}
function normalizeKey(value) { return String(value || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, ''); }
const results = [];
for (const documentItem of documentItems) {
  const document = documentItem.json || {};
  const extraction = document.extraction || {};
  const dispatchKey = normalizeKey(extraction.dispatchReference);
  const matchingDispatches = dispatchRows.filter((row) => normalizeKey(row[document.dispatchReferenceColumn]) === dispatchKey);
  const dispatch = matchingDispatches.length === 1 ? matchingDispatches[0] : null;
  const duplicateDocument = existingRegisterRows.some((row) => String(row['Document Key'] || '') === String(document.documentKey || ''));
  const alreadyBillingReady = existingBillingRows.some((row) => normalizeKey(row['Dispatch Reference']) === dispatchKey);
  const reasons = [];
  if (document.extractionError) reasons.push('Extraction error: ' + document.extractionError);
  if (!extraction.documentReadable) reasons.push('Document is unreadable or not recognised as a completion document.');
  if (!dispatchKey) reasons.push('No dispatch reference was extracted.');
  if (matchingDispatches.length === 0 && dispatchKey) reasons.push('No dispatch matches the extracted reference.');
  if (matchingDispatches.length > 1) reasons.push('More than one dispatch matches the extracted reference.');
  if (extraction.confidence < Number(document.minimumConfidence || 0.8)) reasons.push('Confidence ' + extraction.confidence + ' is below the configured threshold.');
  if (!extraction.signaturePresent) reasons.push('No recipient signature was detected.');
  let status = 'Confirmed';
  let needsReview = false;
  if (duplicateDocument) { status = 'Duplicate'; reasons.push('This exact attachment is already present in POD Register.'); }
  else if (alreadyBillingReady && dispatchKey) { status = 'Duplicate'; reasons.push('This dispatch already has a billing-ready evidence record.'); }
  else if (reasons.length > 0) { status = 'Needs review'; needsReview = true; }
  const safeReference = extraction.dispatchReference || 'no-reference';
  const safeFilename = String(document.sourceFileName || 'document').replace(/[^A-Za-z0-9._-]+/g, '-');
  results.push({ json: { ...document, status, needsReview, exceptionReason: reasons.join(' '), matchedDispatch: dispatch || {}, matchedCustomer: dispatch ? String(dispatch[document.dispatchCustomerColumn] || '') : '', archiveFileName: status.replace(/\s+/g, '-') + '_' + safeReference + '_' + safeFilename }, binary: documentItem.binary || {} });
}
return results;

// 09a. Score evidence and decide billing readiness
// Converts extraction quality into a transparent business decision.
const results = [];
for (const item of $input.all()) {
  const data = item.json || {};
  const extraction = data.extraction || {};
  const hasDispatch = Object.keys(data.matchedDispatch || {}).length > 0;
  const score =
    (hasDispatch ? 35 : 0) +
    (extraction.dispatchReference ? 15 : 0) +
    (extraction.documentReadable ? 15 : 0) +
    Math.round(Math.max(0, Math.min(1, Number(extraction.confidence || 0))) * 25) +
    (extraction.signaturePresent ? 10 : 0);
  const passesPolicy = data.status === 'Confirmed' && score >= Number(data.billingReadyThreshold || 85);
  const reason = passesPolicy
    ? data.exceptionReason
    : (data.status === 'Confirmed' ? `${data.exceptionReason} Evidence score ${score}/100 is below the billing threshold.`.trim() : data.exceptionReason);

  results.push({
    json: {
      ...data,
      evidenceScore: score,
      billingReady: passesPolicy,
      status: passesPolicy ? 'Billing ready' : (data.status === 'Confirmed' ? 'Needs review' : data.status),
      needsReview: data.needsReview || (data.status === 'Confirmed' && !passesPolicy),
      exceptionReason: reason,
    },
    binary: item.binary || {},
  });
}
return results;

// 11. Restore context after Google Drive
// Google Drive replaces input data, so every result is matched to the upstream record by archive name.
const driveResults = $input.all();
let upstreamItems = [];
try { upstreamItems = $('Score Billing Evidence').all(); } catch (error) {}

const results = [];
const restoredNames = new Set();
for (const driveResult of driveResults) {
  const driveJson = driveResult.json || {};
  const archiveName = String(driveJson.name || '');
  const source = upstreamItems.find((item) => String(item.json?.archiveFileName || '') === archiveName);
  if (!source) continue;
  restoredNames.add(archiveName);
  const archiveFailed = Boolean(driveJson.error || driveJson.message?.error);
  const priorReasons = String(source.json.exceptionReason || '');
  const exceptionReason = archiveFailed
    ? (priorReasons + ' Google Drive archive failed: ' + String(driveJson.message || driveJson.error || 'unknown error')).trim()
    : priorReasons;
  results.push({
    json: {
      ...source.json,
      status: archiveFailed && source.json.status === 'Billing ready' ? 'Needs review' : source.json.status,
      billingReady: source.json.billingReady && !archiveFailed,
      needsReview: source.json.needsReview || archiveFailed,
      exceptionReason,
      archiveFileId: driveJson.id || '',
      archiveFileUrl: driveJson.id ? ('https://drive.google.com/open?id=' + driveJson.id) : '',
    },
    binary: source.binary || {},
  });
}

for (const source of upstreamItems) {
  const archiveName = String(source.json?.archiveFileName || '');
  if (!archiveName || restoredNames.has(archiveName)) continue;
  results.push({
    json: {
      ...source.json,
      status: source.json.status === 'Billing ready' ? 'Needs review' : source.json.status,
      billingReady: false,
      needsReview: true,
      exceptionReason: (String(source.json.exceptionReason || '') + ' Google Drive did not return an archive confirmation.').trim(),
      archiveFileId: '',
      archiveFileUrl: '',
    },
    binary: source.binary || {},
  });
}
return results;

// 12. Prepare POD register row
// Returns only POD Register columns so the Google Sheets write remains clean and non-blocking.
const results = [];
for (const item of $input.all()) {
  const data = item.json || {};
  const extraction = data.extraction || {};
  results.push({ json: {
    'Processed At': new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto' }),
    'Status': data.status || 'Needs review',
    'Dispatch Reference': extraction.dispatchReference || '',
    'Customer': data.matchedCustomer || extraction.customer || '',
    'Delivery Date': extraction.deliveryDate || '',
    'Recipient': extraction.recipientName || '',
    'Signature Present': extraction.signaturePresent ? 'Yes' : 'No',
    'Confidence': extraction.confidence ?? 0,
    'Evidence Score': data.evidenceScore ?? 0,
    'Source File': data.sourceFileName || '',
    'Source Message ID': data.sourceMessageId || '',
    'Document Key': data.documentKey || '',
    'Exception Reason': data.exceptionReason || '',
    'Archive File Name': data.archiveFileName || '',
    'Archive File ID': data.archiveFileId || '',
    'Archive File URL': data.archiveFileUrl || '',
  }});
}
return results;

// 23. Build owner-level cash-risk digest
// Finds completed jobs that still lack billable evidence and produces one actionable digest per owner.
const billingRows = $input.all().map((item) => item.json || {});
let dispatchRows = [];
let auditContext = {};
try { dispatchRows = $('Read Audit Dispatches').all().map((item) => item.json || {}); } catch (error) {}
try { auditContext = $('Identify Execution Type').all().find((item) => item.json?.executionType === 'dailyAudit')?.json || {}; } catch (error) {}
const normalize = (value) => String(value || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
const amount = (value) => Number(String(value || '').replace(/[^0-9.-]/g, '')) || 0;
const today = Date.now();
const lateMs = Number(auditContext.lateAfterHours || 24) * 60 * 60 * 1000;
const billable = new Set(billingRows.map((row) => normalize(row['Dispatch Reference'])));
const groups = new Map();
for (const dispatch of dispatchRows) {
  const reference = String(dispatch[auditContext.dispatchReferenceColumn] || '');
  const key = normalize(reference);
  const value = amount(dispatch[auditContext.invoiceAmountColumn]);
  const due = Date.parse(String(dispatch['Scheduled Delivery Date'] || ''));
  if (!key || billable.has(key) || !Number.isFinite(due) || due + lateMs >= today) continue;
  const owner = String(dispatch[auditContext.ownerEmailColumn] || auditContext.reviewerEmail || '').trim() || auditContext.reviewerEmail;
  if (!groups.has(owner)) groups.set(owner, { ownerEmail: owner, revenueAtRisk: 0, jobs: [] });
  const group = groups.get(owner);
  group.revenueAtRisk += value;
  group.jobs.push({ reference, customer: String(dispatch[auditContext.dispatchCustomerColumn] || 'Unknown customer'), value, ageHours: Math.floor((today - due) / 3600000) });
}
const auditDate = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Toronto' });
if (groups.size === 0) return [{ json: { ...auditContext, ownerEmail: auditContext.reviewerEmail, auditDate, revenueAtRisk: 0, missingCount: 0, missingList: 'No late jobs are missing billable evidence.', status: 'clear' } }];
return [...groups.values()].map((group) => ({ json: {
  ...auditContext,
  ...group,
  auditDate,
  missingCount: group.jobs.length,
  missingList: group.jobs.map((job) => job.reference + ' — ' + job.customer + ' — $' + job.value.toFixed(2) + ' — ' + job.ageHours + 'h overdue').join('\n'),
  status: 'action-required',
}}));

