// 17. Prepare automatic billing-ready queue
// Produces a clean, integration-neutral queue for accounting or ERP automation.
return $input.all().map((item) => {
  const data = item.json || {};
  const extraction = data.extraction || {};
  const amount = Number(String(data.matchedDispatch?.[data.invoiceAmountColumn] || '').replace(/[^0-9.-]/g, '')) || 0;
  return { json: {
    'Ready At': new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto' }),
    'Release Source': 'Automatic evidence policy',
    'Document Key': data.documentKey || '',
    'Dispatch Reference': extraction.dispatchReference || '',
    'Customer': data.matchedCustomer || extraction.customer || '',
    'Delivery Date': extraction.deliveryDate || '',
    'Invoice Amount': amount,
    'Evidence Score': data.evidenceScore ?? 0,
    'Source File': data.sourceFileName || '',
    'Archive File URL': data.archiveFileUrl || '',
  }};
});

// 14a. Prepare reviewer queue row
// Creates a durable, human-readable exception record. The reviewer changes only Review Decision.
return $input.all().map((item) => {
  const data = item.json || {};
  const extraction = data.extraction || {};
  return { json: {
    'Review Status': 'Pending',
    'Review Decision': '',
    'Reviewed At': '',
    'Released At': '',
    'Release Note': '',
    'Document Key': data.documentKey || '',
    'Dispatch Reference': extraction.dispatchReference || '',
    'Customer': data.matchedCustomer || extraction.customer || '',
    'Invoice Amount': Number(String(data.matchedDispatch?.[data.invoiceAmountColumn] || '').replace(/[^0-9.-]/g, '')) || 0,
    'Evidence Score': data.evidenceScore ?? 0,
    'Confidence': extraction.confidence ?? 0,
    'Signature Present': extraction.signaturePresent ? 'Yes' : 'No',
    'Exception Reason': data.exceptionReason || 'Manual review requested.',
    'Source File': data.sourceFileName || '',
    'Archive File URL': data.archiveFileUrl || '',
    'Received At': data.receivedAt || '',
  }};
});

// 32. Prepare human decisions for release
// Reads only unprocessed Approve or Reject decisions; approved dispatches already in Billing Ready remain idempotent.
const billingRows = $input.all().map((item) => item.json || {});
let reviewRows = [];
let config = {};
try { reviewRows = $('Read Review Queue').all().map((item) => item.json || {}); } catch (error) {}
try { config = $('Set Template Fields').first().json || {}; } catch (error) {}
const normalize = (value) => String(value || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
const existing = new Set(billingRows.map((row) => normalize(row['Dispatch Reference'])));
const now = new Date().toLocaleString('en-CA', { timeZone: 'America/Toronto' });
const results = [];
for (const row of reviewRows) {
  const decision = String(row['Review Decision'] || '').trim().toLowerCase();
  const reviewStatus = String(row['Review Status'] || '').trim().toLowerCase();
  if (!['approve', 'reject'].includes(decision) || ['approved', 'rejected', 'already released'].includes(reviewStatus)) continue;
  const reference = String(row['Dispatch Reference'] || '');
  const duplicateBillingRecord = existing.has(normalize(reference));
  const approved = decision === 'approve' && !duplicateBillingRecord;
  const finalStatus = decision === 'reject' ? 'Rejected' : (duplicateBillingRecord ? 'Already released' : 'Approved');
  results.push({ json: {
    ...row,
    ...config,
    reviewApproved: approved,
    'Review Status': finalStatus,
    'Reviewed At': now,
    'Released At': approved ? now : String(row['Released At'] || ''),
    'Release Note': decision === 'reject' ? 'Reviewer rejected this evidence.' : (duplicateBillingRecord ? 'A billing-ready record already exists for this dispatch.' : 'Released after human approval.'),
    'Release Source': 'Human review',
    'Ready At': now,
  }});
}
return results;

// 34. Prepare approved manual release
// Keeps Billing Ready independent of the review-sheet row number and preserves configuration for the final status update.
return $input.all().map((item) => {
  const row = item.json || {};
  return { json: {
    'Ready At': row['Ready At'] || '',
    'Release Source': row['Release Source'] || 'Human review',
    'Document Key': row['Document Key'] || '',
    'Dispatch Reference': row['Dispatch Reference'] || '',
    'Customer': row['Customer'] || '',
    'Delivery Date': row['Delivery Date'] || '',
    'Invoice Amount': Number(String(row['Invoice Amount'] || '').replace(/[^0-9.-]/g, '')) || 0,
    'Evidence Score': Number(row['Evidence Score'] || 0),
    'Source File': row['Source File'] || '',
    'Archive File URL': row['Archive File URL'] || '',
    dispatchSheetId: row.dispatchSheetId || '',
    reviewQueueSheetTab: row.reviewQueueSheetTab || '',
    _reviewRow: row,
  }};
});

// 36. Restore review rows only after Billing Ready accepted the append.
// The preceding write is intentionally blocking: a failed billing write leaves the review pending for a safe retry.
let approvedRows = [];
try { approvedRows = $('Prepare Manual Billing Release').all(); } catch (error) {}
return approvedRows.map((item) => ({ json: item.json._reviewRow || item.json }));
